begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) values('ac000000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','ledger-owner@example.test',now(),now(),now()),('ac000000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','ledger-secretary@example.test',now(),now(),now());
insert into public.organizations(id,name,slug,status) values('bc000000-0000-4000-8000-000000000001','Livro A','ledger-a','active'),('bc000000-0000-4000-8000-000000000002','Livro B','ledger-b','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values('cc000000-0000-4000-8000-000000000001','bc000000-0000-4000-8000-000000000001','Sede livro','sede','headquarters'),('cc000000-0000-4000-8000-000000000002','bc000000-0000-4000-8000-000000000002','Sede livro B','sede','headquarters');
insert into public.organization_memberships(organization_id,user_id,role,status,default_unit_id) values('bc000000-0000-4000-8000-000000000001','ac000000-0000-4000-8000-000000000001','owner','active','cc000000-0000-4000-8000-000000000001'),('bc000000-0000-4000-8000-000000000001','ac000000-0000-4000-8000-000000000002','secretary','active','cc000000-0000-4000-8000-000000000001');
select ok(not has_table_privilege('authenticated','public.church_ledger_lines','INSERT'),'cliente não fabrica linhas');
select ok(not has_table_privilege('authenticated','public.church_ledger_journals','UPDATE'),'cliente não reescreve movimentos');
select ok(not has_table_privilege('authenticated','public.church_ledger_journals','DELETE'),'cliente não apaga movimentos');
select ok(not has_function_privilege('anon','public.post_church_journal(uuid,uuid,uuid,date,text,jsonb,uuid)','EXECUTE'),'visitante não lança');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ac000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('vinha.ledger_asset',public.create_church_ledger_account('bc000000-0000-4000-8000-000000000001','cc000000-0000-4000-8000-000000000001','Banco','asset')::text,true);
select set_config('vinha.ledger_income',public.create_church_ledger_account('bc000000-0000-4000-8000-000000000001','cc000000-0000-4000-8000-000000000001','Ofertas','income')::text,true);
select set_config('vinha.ledger_lines',jsonb_build_array(jsonb_build_object('accountId',current_setting('vinha.ledger_asset'),'deltaCents',12345),jsonb_build_object('accountId',current_setting('vinha.ledger_income'),'deltaCents',-12345))::text,true);
select lives_ok($$select public.post_church_journal('bc000000-0000-4000-8000-000000000001','cc000000-0000-4000-8000-000000000001','dc000000-0000-4000-8000-000000000001',current_date-2,'Oferta sintética',current_setting('vinha.ledger_lines')::jsonb)$$,'lançamento balanceado confirma');
select lives_ok($$select public.post_church_journal('bc000000-0000-4000-8000-000000000001','cc000000-0000-4000-8000-000000000001','dc000000-0000-4000-8000-000000000001',current_date-2,'Oferta sintética',current_setting('vinha.ledger_lines')::jsonb)$$,'reexecução idêntica é segura');
select is((select count(*) from public.church_ledger_journals),1::bigint,'reexecução não duplica');
select is((select sum(delta_cents) from public.church_ledger_lines),0::numeric,'livro permanece balanceado em centavos');
select is(public.church_ledger_balances('bc000000-0000-4000-8000-000000000001','cc000000-0000-4000-8000-000000000001',current_date)->0->>'balanceCents','12345','relatório preserva centavos exatos como texto');
select throws_ok($$select public.post_church_journal('bc000000-0000-4000-8000-000000000001','cc000000-0000-4000-8000-000000000001','dc000000-0000-4000-8000-000000000001',current_date-2,'Valor adulterado',current_setting('vinha.ledger_lines')::jsonb)$$,'22023',null,'mesmo identificador não altera conteúdo');
select throws_ok($$select public.post_church_journal('bc000000-0000-4000-8000-000000000002','cc000000-0000-4000-8000-000000000002','dc000000-0000-4000-8000-000000000002',current_date-2,'Outra igreja',current_setting('vinha.ledger_lines')::jsonb)$$,'42501',null,'outra organização é negada');
select throws_ok($$select public.post_church_journal('bc000000-0000-4000-8000-000000000001','cc000000-0000-4000-8000-000000000001','dc000000-0000-4000-8000-000000000002',current_date-2,'Sem balanço',jsonb_set(current_setting('vinha.ledger_lines')::jsonb,'{0,deltaCents}','12344'))$$,'22023',null,'movimento desbalanceado é recusado');
select throws_ok($$select public.post_church_journal('bc000000-0000-4000-8000-000000000001','cc000000-0000-4000-8000-000000000001','dc000000-0000-4000-8000-000000000002',current_date-2,'Centavos fracionados',jsonb_set(current_setting('vinha.ledger_lines')::jsonb,'{0,deltaCents}','123.45'))$$,'22023',null,'centavos fracionados são recusados');
select is((select count(*) from public.church_ledger_journals),1::bigint,'recusas não deixam cabeçalhos parciais');
select lives_ok($$select public.close_church_ledger_period('bc000000-0000-4000-8000-000000000001','cc000000-0000-4000-8000-000000000001',current_date-1)$$,'fecha período anterior');
select throws_ok($$select public.post_church_journal('bc000000-0000-4000-8000-000000000001','cc000000-0000-4000-8000-000000000001','dc000000-0000-4000-8000-000000000002',current_date-2,'Retroativo bloqueado',current_setting('vinha.ledger_lines')::jsonb)$$,'22023',null,'período fechado não recebe retroativos');
select lives_ok($$select public.post_church_journal('bc000000-0000-4000-8000-000000000001','cc000000-0000-4000-8000-000000000001','dc000000-0000-4000-8000-000000000003',current_date,'Estorno autorizado','[]','dc000000-0000-4000-8000-000000000001')$$,'estorno em período aberto preserva original');
select is((select sum(delta_cents) from public.church_ledger_lines where account_id=current_setting('vinha.ledger_asset')::uuid),0::numeric,'estorno neutraliza saldo da conta');
select is(public.church_ledger_balances('bc000000-0000-4000-8000-000000000001','cc000000-0000-4000-8000-000000000001',current_date)->0->>'balanceCents','0','relatório inclui estorno em sua data efetiva');
select throws_ok($$select public.post_church_journal('bc000000-0000-4000-8000-000000000001','cc000000-0000-4000-8000-000000000001','dc000000-0000-4000-8000-000000000004',current_date,'Segundo estorno','[]','dc000000-0000-4000-8000-000000000001')$$,'23505',null,'não duplica estorno');
select set_config('request.jwt.claims','{"sub":"ac000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(*) from public.church_ledger_journals),0::bigint,'secretaria não lê financeiro');
select throws_ok($$select public.create_church_ledger_account('bc000000-0000-4000-8000-000000000001','cc000000-0000-4000-8000-000000000001','Conta indevida','asset')$$,'42501',null,'secretaria não cria conta');
reset role;
select is((select count(*) from public.audit_logs where organization_id='bc000000-0000-4000-8000-000000000001' and action in('ledger.posted','ledger.reversed')),2::bigint,'auditoria confirma somente movimentos efetivos');
select * from finish();
rollback;
